/**
 * Netscape cookie 文件格式的生成与修复。
 *
 * 关键约束（来自 Python http.cookiejar.MozillaCookieJar._really_load）：
 *   domain, domain_specified, path, secure, expires, name, value = line.split("\t")
 *   ...
 *   initial_dot = domain.startswith(".")
 *   assert domain_specified == initial_dot
 *
 * 即：第 2 列的 TRUE/FALSE 标志必须与「域名是否以 . 开头」严格一致，
 * 否则 cookiejar 抛 AssertionError，yt-dlp 报
 * "invalid Netscape format cookies file"。
 */

/** 把 Playwright 的 cookie 对象数组转成 Netscape 格式文本 */
export function toNetscape(cookies) {
  const lines = [
    '# Netscape HTTP Cookie File',
    '# Generated by xvideos-login.mjs - 仅供本机下载使用',
    '',
  ]
  const now = Math.floor(Date.now() / 1000)
  for (const c of cookies) {
    // 域名列保持浏览器原样：带点是 domain cookie，不带点是 host-only cookie
    const domain = c.domain
    // 第 2 列必须与「域名是否以 . 开头」一致，否则触发 cookiejar 断言
    const domainSpecified = domain.startsWith('.') ? 'TRUE' : 'FALSE'
    const secure = c.secure ? 'TRUE' : 'FALSE'
    // expires<=0 表示会话 cookie，写 0 会被 cookiejar 当作 discard 直接丢弃
    const expires =
      c.expires && c.expires > 0 ? Math.floor(c.expires) : now + 365 * 24 * 3600
    const prefix = c.httpOnly ? '#HttpOnly_' : ''
    lines.push(
      [
        prefix + domain,
        domainSpecified,
        c.path || '/',
        secure,
        expires,
        c.name,
        c.value ?? '',
      ].join('\t'),
    )
  }
  return lines.join('\n') + '\n'
}

/**
 * 修复已有的 Netscape cookie 文件。
 * 只调整第 2 列标志位（与域名点号一致性对齐）与过期时间，不动其它字段。
 *
 * @param {string} text 原始文件内容
 * @returns {{text: string, changed: number, total: number}}
 */
export function repairNetscape(text) {
  const now = Math.floor(Date.now() / 1000)
  const out = []
  let changed = 0
  let total = 0

  for (const raw of text.split('\n')) {
    const line = raw
    if (!line.trim() || line.trimStart().startsWith('#')) {
      out.push(raw)
      continue
    }

    const httpOnly = line.startsWith('#HttpOnly_')
    const body = httpOnly ? line.slice('#HttpOnly_'.length) : line
    const fields = body.split('\t')
    if (fields.length < 6) {
      out.push(raw)
      continue
    }

    total++
    const [domain, flag, ...rest] = fields
    const wantFlag = domain.startsWith('.') ? 'TRUE' : 'FALSE'
    if (flag !== wantFlag) changed++

    // 过期时间为空或已过期时，给一个未来时间，避免被 cookiejar 判定为过期丢弃
    const expiresIdx = 3
    const rawExpires = rest[expiresIdx - 2]
    const expires = Number(rawExpires)
    let fixedExpires = rawExpires
    if (!Number.isFinite(expires) || expires <= 0 || expires < now) {
      fixedExpires = String(now + 365 * 24 * 3600)
      changed++
    }

    const newFields = [domain, wantFlag, ...rest]
    newFields[expiresIdx] = fixedExpires
    out.push((httpOnly ? '#HttpOnly_' : '') + newFields.join('\t'))
  }

  return { text: out.join('\n'), changed, total }
}
